mapper.select:
with recursive visible as ( select f.*, () as writable from ai_knowledge_folder f join ai_knowledge_base b on b.id = f.knowledge_base_id and b.del_flag = 0 where f.del_flag = 0 and f.knowledge_base_id = #{knowledgeBaseId} and ( or exists (select 1 from ai_knowledge_document d where d.folder_id = f.id and d.del_flag = 0 and d.is_public = true))
and f.data_status = #{dataStatus}
), paths as ( select * from visible union select p.*, child.writable from ai_knowledge_folder p join paths child on p.id = child.parent_id and p.knowledge_base_id = child.knowledge_base_id where p.del_flag = 0 ) select * from paths order by sort_order, id
